@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--lime:#d8ff68;--ink:#131a17;--panel:rgba(17,25,21,.82);--muted:#a9b5a7;--line:rgba(230,255,220,.15)}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:#18251d;color:#fff;font-family:'DM Sans',sans-serif;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#27382a}canvas#game{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 55%,rgba(5,12,8,.35) 100%);z-index:1}.topbar{position:absolute;z-index:2;left:0;right:0;top:0;padding:20px 30px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,15,12,.72),transparent)}.brand{display:flex;align-items:center;gap:10px}.brand-mark{width:37px;height:37px;border:1px solid rgba(216,255,104,.55);border-radius:11px;color:var(--lime);font-size:24px;display:grid;place-items:center;transform:rotate(-8deg)}.brand b{font:800 19px 'Barlow Condensed',sans-serif;letter-spacing:2px;display:block}.brand small{font-size:8px;letter-spacing:2.1px;color:#b1beaf}.match-pill{background:rgba(15,24,19,.78);border:1px solid var(--line);border-radius:30px;padding:8px 14px;font-size:9px;letter-spacing:1.6px;font-weight:800;display:flex;align-items:center;gap:8px}.live-dot,.zone-pulse{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px var(--lime)}.icon-button{width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:rgba(17,25,21,.7);font-size:17px;cursor:pointer}.hud{position:absolute;z-index:2;top:83px;left:30px;right:30px;display:flex;align-items:flex-start;gap:9px}.stat-card,.zone-card{height:51px;display:flex;align-items:center;background:var(--panel);border:1px solid var(--line);border-radius:9px;backdrop-filter:blur(8px)}.stat-card{padding:0 12px;gap:9px;min-width:110px}.stat-icon{color:var(--lime);font-size:16px}.stat-card strong{display:block;font:800 18px 'Barlow Condensed',sans-serif;line-height:18px}.stat-card small{display:block;font-size:7px;letter-spacing:1.25px;color:#aab5a8;margin-top:3px}.zone-card{width:210px;padding:8px 11px;display:block}.zone-label{font-size:8px;letter-spacing:1px;color:#dce7dc;font-weight:700;display:flex;align-items:center;gap:6px}.zone-label b{margin-left:auto;color:var(--lime);font-size:10px;font-variant-numeric:tabular-nums}.zone-pulse{width:6px;height:6px}.zone-track{height:3px;background:rgba(255,255,255,.13);border-radius:5px;margin-top:9px;overflow:hidden}.zone-track i{height:100%;width:100%;display:block;background:var(--lime);transition:width .25s}.mini-map-wrap{position:absolute;right:0;top:0;width:144px;text-align:center}.mini-map-wrap canvas{width:106px;height:106px;border:2px solid rgba(224,255,208,.72);border-radius:50%;background:#293c2c;box-shadow:0 5px 25px #0006}.map-caption{display:block;font-size:7px;letter-spacing:1.3px;color:#e0e9dd;text-shadow:0 1px 5px #000}.crosshair{position:absolute;z-index:2;left:50%;top:50%;width:15px;height:15px;transform:translate(-50%,-50%);opacity:.5;pointer-events:none}.crosshair:before,.crosshair:after{content:'';position:absolute;background:#fff}.crosshair:before{width:1px;height:15px;left:7px}.crosshair:after{height:1px;width:15px;top:7px}.crosshair i{position:absolute;inset:5px;border:1px solid #fff;border-radius:50%}.bottom-hud{position:absolute;z-index:2;bottom:24px;left:30px;display:flex;align-items:flex-end;gap:9px}.player-card,.weapon-card{background:var(--panel);border:1px solid var(--line);border-radius:10px;backdrop-filter:blur(8px);padding:11px 13px}.player-card{width:190px}.player-heading{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.4px;color:#dce8da;margin-bottom:8px}.player-heading b{color:var(--lime);font-size:8px}.meter-row{display:flex;align-items:center;gap:7px;margin:6px 0}.meter-icon{font-size:11px;width:12px}.health-icon{color:#ff706c}.shield-icon{color:#74c9ff}.meter{height:6px;flex:1;background:rgba(255,255,255,.12);border-radius:5px;overflow:hidden}.meter i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#ff595c,#ff8e76);border-radius:5px;transition:width .25s}.shield-meter i{background:linear-gradient(90deg,#41a9ff,#8be5ff)}.meter-row strong{font:700 11px 'Barlow Condensed',sans-serif;min-width:22px;text-align:right}.weapon-card{width:168px;min-height:77px}.weapon-top{display:flex;align-items:center;justify-content:space-between;font:700 10px 'Barlow Condensed',sans-serif;letter-spacing:1px}.weapon-tag{font:700 7px 'DM Sans';padding:3px 5px;border-radius:4px;background:rgba(216,255,104,.14);color:var(--lime)}.ammo{display:flex;align-items:center;gap:5px;margin-top:0;font:700 10px 'Barlow Condensed',sans-serif;color:#9da99c}.ammo strong{font:800 27px 'Barlow Condensed',sans-serif;color:white}.ammo small{font-size:12px}.ammo button{margin-left:auto;background:none;border:0;color:var(--lime);font-size:19px;cursor:pointer}.weapon-caption{font-size:7px;letter-spacing:1px;color:#b0b9ad}.weapon-caption span{color:var(--lime)}kbd{font-size:7px;border:1px solid #677164;border-radius:3px;padding:1px 3px;color:#e4eadf}.feedback{position:absolute;left:100%;bottom:0;white-space:nowrap;margin-left:10px;color:var(--lime);font:800 12px 'Barlow Condensed';letter-spacing:1px;text-shadow:0 2px 6px #000;opacity:0;transition:opacity .2s}.feedback.show{opacity:1}.touch-controls{position:absolute;z-index:3;inset:0;pointer-events:none;display:none}.joystick{position:absolute;left:7vw;bottom:8vh;width:118px;height:118px;border-radius:50%;pointer-events:auto;touch-action:none}.joy-ring{position:absolute;inset:0;border-radius:50%;background:rgba(220,244,214,.07);border:1px solid rgba(255,255,255,.25);box-shadow:inset 0 0 25px #0003}.joy-knob{position:absolute;width:52px;height:52px;left:33px;top:33px;border-radius:50%;background:rgba(217,255,104,.35);border:1px solid rgba(217,255,104,.8);box-shadow:0 3px 12px #0005}.joy-label{position:absolute;left:0;right:0;bottom:-17px;text-align:center;font-size:8px;font-weight:700;letter-spacing:2px;color:#d9e3d4;text-shadow:0 1px 4px #000}.action-controls{position:absolute;right:5vw;bottom:7vh;display:flex;gap:15px;align-items:flex-end;pointer-events:auto}.fire-btn,.action-btn{border:0;touch-action:none;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;box-shadow:0 8px 20px #0005}.fire-btn{width:94px;height:94px;border-radius:50%;background:rgba(235,95,67,.88);border:2px solid rgba(255,222,193,.8);box-shadow:0 0 0 7px rgba(235,95,67,.15),0 8px 20px #0006}.fire-btn:active{transform:scale(.94);background:#f2795c}.fire-core{font-size:31px;line-height:32px}.fire-btn b{font:800 10px 'Barlow Condensed';letter-spacing:1px}.fire-btn small{font-size:6px;opacity:.8;margin-top:2px}.action-btn{width:58px;height:58px;border-radius:17px;background:rgba(17,25,21,.8);border:1px solid var(--line)}.heal-btn span{font-size:23px;color:var(--lime)}.heal-btn small{font-size:7px;letter-spacing:.6px}.heal-btn small b{color:var(--lime)}.toast{position:absolute;z-index:3;top:22%;left:50%;transform:translateX(-50%);background:rgba(12,20,15,.86);border:1px solid #d8ff6866;color:#eaffb5;border-radius:7px;padding:9px 15px;font-size:10px;letter-spacing:1px;font-weight:700;opacity:0;transition:opacity .2s;pointer-events:none}.toast.show{opacity:1}.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(9,17,13,.83),rgba(9,17,13,.48) 45%,rgba(9,17,13,.12)),linear-gradient(0deg,rgba(8,14,10,.5),transparent 40%);transition:opacity .35s}.overlay.hidden{opacity:0;pointer-events:none}.menu-card{width:min(410px,90vw);margin-left:min(10vw,130px);text-align:left}.eyebrow{display:flex;align-items:center;gap:9px;color:var(--lime);font-size:9px;font-weight:800;letter-spacing:2px}.eyebrow span{height:1px;width:20px;background:var(--lime)}h1{font:900 clamp(76px,10vw,112px)/.73 'Barlow Condensed',sans-serif;letter-spacing:-2px;margin:23px 0 19px;text-shadow:0 8px 30px #0005}h1 em{font-style:normal;color:var(--lime)}.menu-card>p{font-size:13px;line-height:1.7;color:#d3dcd0;margin:0 0 23px}.drop-info{display:flex;align-items:center;gap:11px;width:275px;background:rgba(226,245,219,.1);border:1px solid rgba(230,255,220,.2);padding:10px;border-radius:7px;margin-bottom:12px}.drop-icon{color:var(--lime);font-size:21px}.drop-info b,.drop-info small{display:block}.drop-info b{font-size:9px;letter-spacing:1px}.drop-info small{font-size:7px;color:#aab7a7;letter-spacing:1px;margin-top:4px}.drop-arrow{margin-left:auto;color:var(--lime);font-size:17px}.start-button{width:275px;height:48px;border:0;border-radius:6px;background:var(--lime);color:#182114;font:900 12px 'DM Sans';letter-spacing:1.4px;text-align:left;padding:0 17px;cursor:pointer;box-shadow:0 5px 25px #d8ff6826}.start-button span{float:right;font-size:18px;line-height:12px}.start-button:hover{background:#e5ff9b;transform:translateY(-1px)}.control-tip,.mobile-tip{margin-top:19px;color:#c0cbbc;font-size:7px;letter-spacing:1px}.control-tip b{color:#fff}.control-tip i,.mobile-tip i{color:var(--lime);font-style:normal;padding:0 4px}.mobile-tip{display:none}.end-card{text-align:center;margin:0 auto}.end-card .eyebrow{justify-content:center}.end-card h2{font:900 66px 'Barlow Condensed';color:var(--lime);margin:14px 0 2px}.end-card>p{margin:0 0 20px}.end-stats{display:flex;justify-content:center;gap:35px;margin-bottom:22px}.end-stats b,.end-stats small{display:block}.end-stats b{font:800 28px 'Barlow Condensed'}.end-stats small{font-size:8px;color:#adb8aa;letter-spacing:1px}.end-card .start-button{text-align:center}.end-card .start-button span{float:none;margin-left:12px}.rotate-hint{display:none}
@media (pointer:coarse),(max-width:760px){.touch-controls{display:block}.mobile-tip{display:block}.control-tip{display:none}.topbar{padding:12px 14px}.brand-mark{width:31px;height:31px;font-size:20px;border-radius:9px}.brand b{font-size:15px}.brand small{font-size:6px}.icon-button{width:30px;height:30px}.hud{top:59px;left:12px;right:12px;gap:5px}.stat-card{min-width:68px;height:41px;padding:0 7px;gap:5px}.stat-icon{font-size:12px}.stat-card strong{font-size:15px;line-height:15px}.stat-card small{font-size:5px;letter-spacing:.7px}.zone-card{height:41px;width:118px;padding:6px}.zone-label{font-size:6px;letter-spacing:.5px;gap:4px}.zone-label b{font-size:8px}.zone-track{margin-top:7px}.mini-map-wrap{width:78px}.mini-map-wrap canvas{width:70px;height:70px}.map-caption{font-size:5px}.bottom-hud{bottom:12px;left:12px;gap:5px}.player-card{width:132px;padding:8px}.weapon-card{width:118px;min-height:68px;padding:8px}.player-heading{font-size:6px;margin-bottom:5px}.player-heading b{font-size:6px}.meter-row{margin:4px 0;gap:4px}.meter-icon{font-size:9px;width:9px}.meter{height:5px}.meter-row strong{font-size:9px;min-width:16px}.weapon-top{font-size:8px}.weapon-tag{font-size:5px}.ammo{gap:3px}.ammo strong{font-size:22px}.ammo small{font-size:10px}.ammo button{font-size:16px}.weapon-caption{font-size:5px}.weapon-caption kbd{font-size:5px}.feedback{font-size:9px;margin-left:5px}.crosshair{opacity:.3}.menu-card{margin-left:0;width:min(380px,88vw)}h1{font-size:76px;margin:17px 0 14px}.menu-card>p{font-size:11px;margin-bottom:16px}.drop-info,.start-button{width:245px}.drop-info{padding:8px;margin-bottom:9px}.start-button{height:43px}.eyebrow{font-size:8px}.control-tip,.mobile-tip{margin-top:13px;font-size:6px}.end-card h2{font-size:52px}}
@media(max-width:520px) and (orientation:portrait){.rotate-hint{display:block;position:absolute;z-index:4;right:12px;top:50%;writing-mode:vertical-rl;font-size:7px;letter-spacing:1px;color:#fff8}.mini-map-wrap{right:0}}
@media(max-height:500px){.bottom-hud{bottom:9px}.player-card,.weapon-card{padding:7px}.topbar{padding-top:10px}.hud{top:53px}.joystick{bottom:4vh;width:95px;height:95px}.joy-knob{left:27px;top:27px;width:40px;height:40px}.action-controls{bottom:4vh}.fire-btn{width:76px;height:76px}.action-btn{width:48px;height:48px}.menu-card{transform:scale(.85)}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {alive:$('alive-count'),kills:$('kill-count'),timer:$('zone-timer'),progress:$('zone-progress'),health:$('health-fill'),healthText:$('health-text'),shield:$('shield-fill'),shieldText:$('shield-text'),ammo:$('ammo-current'),reserve:$('ammo-reserve'),medkits:$('medkit-count'),toast:$('toast'),feedback:$('feedback'),overlay:$('overlay'),end:$('end-overlay')};
  const W=2600,H=2600,TAU=Math.PI*2, rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  let dpr=1, viewW=innerWidth, viewH=innerHeight, last=0, running=false, elapsed=0, kills=0, toastTimer=0, fireTimer=0, soundOn=false, audio;
  let keys={}, world=[], scenery=[], bullets=[], particles=[], loot=[], bots=[], storm={x:W/2,y:H/2,r:1180,startR:1180,targetR:820,time:80,duration:22,stage:0};
  const player={x:W/2,y:H/2+40,r:16,angle:0,hp:100,shield:50,ammo:30,reserve:120,medkits:2,speed:220,reload:0,invuln:0};
  let pointer={x:viewW*.65,y:viewH*.5,down:false}, joy={x:0,y:0,active:false,id:null}, mobileFire=false, camera={x:0,y:0};
  function resize(){dpr=Math.min(devicePixelRatio||1,2);viewW=innerWidth;viewH=innerHeight;canvas.width=Math.floor(viewW*dpr);canvas.height=Math.floor(viewH*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
  addEventListener('resize',resize);resize();
  function circleHit(x,y,r,o){const nx=clamp(x,o.x,o.x+o.w),ny=clamp(y,o.y,o.y+o.h);return (x-nx)**2+(y-ny)**2<r*r;}
  function collides(x,y,r){return world.some(o=>circleHit(x,y,r,o));}
  function moveEntity(e,dx,dy){if(!collides(e.x+dx,e.y,e.r))e.x+=dx;if(!collides(e.x,e.y+dy,e.r))e.y+=dy;e.x=clamp(e.x,e.r,W-e.r);e.y=clamp(e.y,e.r,H-e.r);}
  function makeWorld(){
    world=[];scenery=[];loot=[];
    // Dense but walkable forest, with clearings around the settlement and spawn.
    for(let i=0;i<42;i++){
      const x=rand(110,W-230),y=rand(110,H-230),w=rand(75,160),h=rand(65,145);
      if(Math.hypot(x-W/2,y-H/2)<240)continue;
      if(world.some(o=>x<o.x+o.w+75&&x+w+75>o.x&&y<o.y+o.h+75&&y+h+75>o.y))continue;
      world.push({x,y,w,h,type:Math.random()<.78?'house':'shed',tone:Math.floor(rand(0,4))});
    }
    for(let i=0;i<330;i++){
      const x=rand(28,W-28),y=rand(28,H-28),r=rand(13,30);
      if(world.some(o=>x>o.x-30&&x<o.x+o.w+30&&y>o.y-30&&y<o.y+o.h+30))continue;
      scenery.push({x,y,r,type:Math.random()<.83?'tree':'rock',tone:Math.random()});
    }
    // Scatter supplies in open ground; the central compound has the best starting loot.
    for(let i=0;i<45;i++){
      let x,y,tries=0;do{x=rand(90,W-90);y=rand(90,H-90);tries++;}while((collides(x,y,18)||Math.hypot(x-W/2,y-H/2)<260)&&tries<100);
      loot.push({x,y,type:Math.random()<.57?'ammo':Math.random()<.76?'med':'shield',pulse:rand(0,TAU)});
    }
    for(let i=0;i<20;i++){
      let x,y;do{x=rand(100,W-100);y=rand(100,H-100);}while(collides(x,y,20)||Math.hypot(x-player.x,y-player.y)<360);
      bots.push({id:i,x,y,r:15,hp:100,shield:rand(0,35),angle:rand(0,TAU),speed:rand(105,145),ammo:30,shot:rand(.3,1.5),think:rand(0,2),wander:rand(0,TAU),alive:true,color:['#e7674f','#e3a34b','#ba76ce','#5eb4a4','#d46682'][i%5],name:['Rook','Viper','Mako','Echo','Nova','Ash','Riot','Kite','Wraith','Jinx'][i%10]});
    }
  }
  function begin(){makeWorld();bullets=[];particles=[];player.x=W/2;player.y=H/2+40;player.hp=100;player.shield=50;player.ammo=30;player.reserve=120;player.medkits=2;player.reload=0;player.invuln=1.5;kills=0;elapsed=0;storm={x:W/2,y:H/2,r:1180,startR:1180,targetR:840,time:28,duration:22,stage:0};running=true;ui.overlay.classList.add('hidden');ui.end.classList.add('hidden');showToast('DROP COMPLETE — FIND COVER');updateHud();last=performance.now();requestAnimationFrame(loop);}
  $('start-button').addEventListener('click',begin);$('again-button').addEventListener('click',begin);
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.1;}
  function flash(text){ui.feedback.textContent=text;ui.feedback.classList.add('show');setTimeout(()=>ui.feedback.classList.remove('show'),900);}
  function updateHud(){ui.alive.textContent=1+bots.filter(b=>b.alive).length;ui.kills.textContent=kills;ui.health.style.width=player.hp+'%';ui.healthText.textContent=Math.ceil(player.hp);ui.shield.style.width=(player.shield/100*100)+'%';ui.shieldText.textContent=Math.ceil(player.shield);ui.ammo.textContent=player.ammo;ui.reserve.textContent=player.reserve;ui.medkits.textContent=player.medkits;}
  function formatTime(s){s=Math.max(0,Math.ceil(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
  function reload(){if(player.reload>0||player.ammo>=30||player.reserve<=0)return;player.reload=1.25;showToast('RELOADING');}
  $('reload-button').addEventListener('click',reload);addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='r')reload();if(e.key===' '){e.preventDefault();shoot();}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
  function setPointer(e){const rect=canvas.getBoundingClientRect();pointer.x=e.clientX-rect.left;pointer.y=e.clientY-rect.top;const wx=pointer.x+camera.x,wy=pointer.y+camera.y;player.angle=Math.atan2(wy-player.y,wx-player.x);}
  canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')setPointer(e)});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){setPointer(e);pointer.down=true;canvas.setPointerCapture(e.pointerId);shoot()}});canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')pointer.down=false});
  function setupJoystick(){const base=$('joystick'),knob=$('joy-knob');function update(e){const r=base.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=36,len=Math.hypot(dx,dy),scale=len>max?max/len:1;joy.x=dx*scale/max;joy.y=dy*scale/max;knob.style.transform=`translate(${joy.x*36}px,${joy.y*36}px)`;if(len>7)aimNearest();}base.addEventListener('pointerdown',e=>{e.preventDefault();joy.active=true;joy.id=e.pointerId;base.setPointerCapture(e.pointerId);update(e)});base.addEventListener('pointermove',e=>{if(joy.active&&e.pointerId===joy.id)update(e)});function end(){joy.active=false;joy.x=joy.y=0;knob.style.transform=''}base.addEventListener('pointerup',end);base.addEventListener('pointercancel',end);}
  setupJoystick();
  function aimNearest(){let nearest=null,nd=620;for(const b of bots){if(!b.alive)continue;const d=dist(player,b);if(d<nd){nd=d;nearest=b;}}if(nearest)player.angle=Math.atan2(nearest.y-player.y,nearest.x-player.x);}
  $('fire-button').addEventListener('pointerdown',e=>{e.preventDefault();mobileFire=true;aimNearest();shoot();$('fire-button').setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>$('fire-button').addEventListener(ev,()=>mobileFire=false));
  $('heal-button').addEventListener('pointerdown',e=>{e.preventDefault();useMedkit()});
  function useMedkit(){if(player.medkits<=0){showToast('NO MEDKITS');return;}if(player.hp>=100){showToast('HEALTH ALREADY FULL');return;}player.medkits--;player.hp=Math.min(100,player.hp+45);showToast('MEDKIT USED  +45 HP');updateHud();tone(520,.08);}
  function tone(freq=160,duration=.06){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
  $('sound-toggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';if(soundOn)tone(600,.08)});
  function shoot(){if(!running||player.reload>0)return;if(player.ammo<=0){reload();return;}player.ammo--;const spread=rand(-.035,.035),a=player.angle+spread;bullets.push({x:player.x+Math.cos(a)*21,y:player.y+Math.sin(a)*21,vx:Math.cos(a)*760,vy:Math.sin(a)*760,life:.85,owner:'player',damage:26});for(let i=0;i<3;i++)particles.push({x:player.x+Math.cos(a)*23,y:player.y+Math.sin(a)*23,vx:rand(-45,45),vy:rand(-45,45),life:.16,color:'#ffe49a',size:rand(2,4)});tone(120,.045);updateHud();}
  function botShoot(b,target){const a=Math.atan2(target.y-b.y,target.x-b.x)+rand(-.12,.12);bullets.push({x:b.x+Math.cos(a)*18,y:b.y+Math.sin(a)*18,vx:Math.cos(a)*520,vy:Math.sin(a)*520,life:.9,owner:b,damage:12});b.shot=rand(.75,1.25);}
  function hit(target,damage,source){if(target===player){if(player.invuln>0)return;let d=damage;if(player.shield>0){const s=Math.min(player.shield,d*.7);player.shield-=s;d-=s;}player.hp-=d;player.invuln=.13;particles.push({x:player.x,y:player.y,vx:rand(-40,40),vy:rand(-40,40),life:.3,color:'#ff7567',size:6});tone(80,.08);if(player.hp<=0)finish(false);updateHud();}else{if(target.shield>0){const s=Math.min(target.shield,damage*.65);target.shield-=s;damage-=s;}target.hp-=damage;particles.push({x:target.x,y:target.y,vx:rand(-30,30),vy:rand(-30,30),life:.25,color:'#ffcf8c',size:4});if(target.hp<=0){target.alive=false;for(let i=0;i<8;i++)particles.push({x:target.x,y:target.y,vx:rand(-85,85),vy:rand(-85,85),life:rand(.25,.55),color:target.color,size:rand(2,5)});if(source==='player'){kills++;flash('ELIMINATION +1');tone(430,.12);if(Math.random()<.42)loot.push({x:target.x+rand(-12,12),y:target.y+rand(-12,12),type:Math.random()<.5?'ammo':'med',pulse:0});}updateHud();}}
  }
  function finish(win){if(!running)return;running=false;$('end-title').textContent=win?'VICTORY':'ELIMINATED';$('end-title').style.color=win?'var(--lime)':'#ff7167';$('end-copy').textContent=win?'The island is yours.':'Your run ends here. Ready for another drop?';$('end-kills').textContent=kills;$('end-time').textContent=formatTime(elapsed);ui.end.classList.remove('hidden');}

